      +'<div class="s-dims one"><label>Vierkante meters<input type="number" inputmode="numeric" id="o-mq" min="'+T.mqMin+'" max="'+T.mqMax+'" step="1"><small>Tel 10% bij voor zaagsnedes en snijverlies</small></label></div></fieldset>';
    h+='<dl class="s-specs"><dt>Formaat</dt><dd>'+esc(t.fmt.map(function(x){return x.replace('x','×')}).join(' · '))+' cm</dd><dt>Dikte</dt><dd>'+esc(t.sp)+'</dd><dt>Afwerking</dt><dd>'+esc(t.fin.join(' / ')||'Naturale')+'</dd><dt>Rand</dt><dd>'+(t.rett?'Gerectificeerd':'Niet gerectificeerd')+'</dd><dt>Materiaal</dt><dd>'+esc(t.mat)+'</dd>'+(t.extra.length?'<dt>Opmerkingen</dt><dd>'+esc(t.extra.join(', '))+'</dd>':'')+'</dl>';
