      var g=doorGeom(c);return [op.label+(c.hand==='sx'?' links':' rechts'), c.size==='custom'?'muuropening '+c.vw+'×'+c.vh+' mm, muur '+c.wall+' mm (deurblad '+g.lw+'×'+g.lh+')':c.w+'×'+PR.door.height+' cm, muur '+c.wall+' mm', p.line==='laminata'?p.finishes[0]:fmGrezza(c)?'onbehandeld om te schilderen':'RAL '+(c.ral||'nog te kiezen')].concat(ex).concat(service(c.serv)?[service(c.serv).label]:['zonder transport en montage']).join(' · ');
