      +'<div class="s-price">'+(many?'<small>vanaf</small>':'')+eur.format(price)+(p.type==='door'?'<span>+ btw · met montage in VE/FVG '+eur.format(price+150)+'</span>':'')+'</div>'
      +'<div class="s-card-foot"><button class="s-add" type="button" data-add="'+esc(p.id)+'" aria-label="Toevoegen '+esc(p.name)+' al carrello">'+IC.plus+'<span>Toevoegen</span></button>'
