      [[l.bundle&&bv[l.bundle]?l.bdisc||0:0,l.bname||'Pakket'],[l.type==='door'&&!l.bundle&&tier?tier.perc:0,tier?tier.label:''],[code?N.perc:0,'code '+code]].forEach(function(c){if(c[0]>best[0])best=c});
