      if(p.custom&&p.limits){var L=p.limits;h+='<figure class="pdp-draw furn note"><div class="pdp-lim"><b>Op maat</b><span>Breedte '+L.w[0]+'–'+L.w[1]+' cm</span><span>Diepte '+L.d[0]+'–'+L.d[1]+' cm</span><span>Hoogte '+L.h[0]+'–'+L.h[1]+' cm</span><a class="s-link" href="#pdp-cfg">Voer uw maten in ↑</a></div><figcaption><b>Op de centimeter gemaakt</b><span>+'+PR.furniture.customPerc+'% op de prijs, naar verhouding</span></figcaption></figure>'}
