    var items=pairs.map(function(pr){var ids=pr[1].map(function(i){return i==='@self'?p.id:i});if(ids.indexOf(p.id)>=0&&pr[1][0]!=='@self')return null;var parts=[p].concat(ids.map(byId));if(parts.some(function(x){return !x}))return null;return{name:pr[0],parts:parts}}).filter(Boolean);
    if(!items.length){box.closest('section').hidden=true;return}
    h='<div class="pdp-bund">'+items.map(function(b,bi){
      var cfgs=b.parts.map(function(q,i){return i===0&&CUR&&CUR.p===p?CUR.c:defaultCfg(q,'')}),prices=b.parts.map(function(q,i){return quote(q,cfgs[i]).unit}),full=prices.reduce(function(a,x){return a+x},0),net=Math.round(full*(1-perc/100));
      return '<div class="pdp-b"><span class="pdp-tag">'+esc(b.name)+' · −'+perc+'%</span><div class="pdp-b-items">'+b.parts.map(function(q,i){return (i?'<i class="pdp-plus">+</i>':'')+'<a class="pdp-b-it" href="'+pURL(q)+'"><span><img '+(q.type==='cube'?'src="/shop/img/prodotti/'+esc(q.id)+'.jpg"':imgAttrs(q))+' alt="" loading="lazy"></span><b>'+esc(q.name)+(i===0?' <em>(deze)</em>':'')+'</b><small>'+eur.format(prices[i])+'</small></a>'}).join('')+'</div>'
        +'<div class="pdp-b-foot"><div><s>'+eur.format(full)+'</s><b>'+eur.format(net)+'</b><span class="pdp-save">U bespaart '+eur.format(full-net)+'</span></div><button type="button" class="s-btn s-btn-p" data-bund="'+bi+'">'+IC.bag+'Pakket toevoegen</button></div></div>';
    }).join('')+'</div><p class="s-note">Prijzen incl. btw met de hierboven gekozen maat en afwerking voor dit product; de andere stukken in de basismaat, met u aan te passen vóór de productie.</p>';
    box.innerHTML=h;
